function Potencia(x: nat, y: nat): nat
{
    if y == 0
    then 1
    else x * Potencia(x, y-1) 
}

method Pot(x: nat, y: nat) returns (r: nat)
ensures r == Potencia(x,y)
{
    var b := x;
    var e := y;
    r := 1;

    while e > 0
      decreases e // candidate
      invariant e >= 0 // candidate
      invariant r == Potencia(b, y - e) // candidate
    {
        r := b * r;
        e := e - 1;
    }

    return r;
}

